import { FormField } from '@absoluteui/components/form-field';

const control = document.createElement('input');
control.name = 'zip';
control.inputMode = 'numeric';
control.autocomplete = 'postal-code';
control.pattern = '[0-9]{5}';
const host = document.createElement('div');
document.body.append(host);
const zip = FormField.create(host, { label: 'ZIP code', control, required: true, description: 'Five digits' });
host.addEventListener('aui-change', () => {
  host.dataset.valid = String(zip.validity.valid);
});

import { FormField, type FormFieldChangeDetail } from '@absoluteui/components/form-field';

const topic = document.createElement('select');
topic.name = 'topic';
topic.add(new Option('Choose a topic', ''));
topic.add(new Option('Billing', 'billing'));
topic.add(new Option('Technical support', 'support'));
const topicHost = document.createElement('div');
document.body.append(topicHost);
FormField.create(topicHost, { label: 'Topic', control: topic, required: true });

const details = document.createElement('textarea');
details.name = 'details';
details.maxLength = 500;
const detailsHost = document.createElement('div');
document.body.append(detailsHost);
FormField.create(detailsHost, {
  label: 'Details',
  control: details,
  validate: (value) => (typeof value === 'string' && /https?:\/\//.test(value) ? 'Remove links from your message.' : null),
});
detailsHost.addEventListener('aui-input', (event) => {
  const { validity } = (event as CustomEvent<FormFieldChangeDetail>).detail;
  detailsHost.dataset.valid = String(validity.valid);
});

import { FormField } from '@absoluteui/components/form-field';

const host = document.querySelector<HTMLElement>('#quantity-field');
const control = host?.querySelector<HTMLInputElement>('input[type="number"]');
if (host && control) {
  const quantity = FormField.create(host, { label: 'Quantity', control });
  // Native attributes are the constraints; re-read them after changing them in code.
  control.max = '10';
  control.value = '12';
  quantity.refresh();
  quantity.reportValidity();
}

import { configureAbsoluteUI } from '@absoluteui/core';
import '@absoluteui/components/form-field';

configureAbsoluteUI({ components: { formField: { validationTiming: 'input' } } });
